app_css:
.tool-app-selectsheet { color: #431407; max-width: 920px; margin-inline: auto; }
.tool-app-selectsheet .ss-proj { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 10px; margin: 12px 0; }
.tool-app-selectsheet .ss-addroom { display: flex; gap: 8px; margin: 10px 0 16px; }
.tool-app-selectsheet label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-selectsheet input[type="text"], .tool-app-selectsheet input[type="number"], .tool-app-selectsheet input[type="date"], .tool-app-selectsheet select { border: 1px solid #fed7aa; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; background: #fff; }
.tool-app-selectsheet input:focus, .tool-app-selectsheet select:focus { outline: 2px solid #C2410C; border-color: #C2410C; }
.tool-app-selectsheet .ss-room { background: #fffbeb; border: 1px solid #fde68a; border-radius: 12px; padding: 12px; margin-bottom: 14px; }
.tool-app-selectsheet .ss-roomhead { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.tool-app-selectsheet .ss-roomhead h3 { margin: 0; font-size: 16px; color: #7c2d12; }
.tool-app-selectsheet .ss-roomheadbtns { display: flex; gap: 6px; align-items: center; }
.tool-app-selectsheet .ss-table { width: 100%; border-collapse: collapse; margin: 6px 0; }
.tool-app-selectsheet .ss-table th { text-align: left; font-size: 11px; color: #92400e; padding: 6px; white-space: nowrap; }
.tool-app-selectsheet .ss-table td { padding: 4px; border-top: 1px solid #fde68a; vertical-align: middle; }
.tool-app-selectsheet .ss-item { min-width: 140px; }
.tool-app-selectsheet .ss-allow, .tool-app-selectsheet .ss-actual { max-width: 96px; }
.tool-app-selectsheet .ss-due { max-width: 140px; }
.tool-app-selectsheet .ss-status { max-width: 130px; }
.tool-app-selectsheet .ss-remove, .tool-app-selectsheet .ss-delroom { background: none; border: none; color: #b91c1c; font-size: 20px; cursor: pointer; line-height: 1; }
.tool-app-selectsheet .ss-btn { background: #C2410C; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-selectsheet .ss-btn:hover { background: #9a3412; }
.tool-app-selectsheet .ss-btn-sm { padding: 6px 12px; font-size: 13px; }
.tool-app-selectsheet .ss-btn-ghost { background: #ffedd5; color: #C2410C; }
.tool-app-selectsheet .ss-btn-ghost:hover { background: #fed7aa; }
.tool-app-selectsheet .ss-roomtotal { display: flex; gap: 16px; align-items: center; font-size: 13px; color: #92400e; margin-top: 8px; flex-wrap: wrap; }
.tool-app-selectsheet .ss-roomtotal strong { color: #431407; }
.tool-app-selectsheet .ss-ledger { background: #fff7ed; border: 1px solid #fed7aa; border-radius: 12px; padding: 14px; margin: 16px 0; }
.tool-app-selectsheet .ss-ledger h3 { margin: 0 0 10px; font-size: 16px; color: #7c2d12; }
.tool-app-selectsheet .ss-ledgertotals { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 12px; }
.tool-app-selectsheet .ss-ledgertotals > div { display: flex; justify-content: space-between; align-items: center; font-size: 14px; }
.tool-app-selectsheet .ss-grand { font-size: 18px; background: #ffedd5; border-radius: 10px; padding: 10px 14px; grid-column: 1 / -1; }
.tool-app-selectsheet .ss-neg { color: #b91c1c; }
.tool-app-selectsheet .ss-ledger h4 { margin: 10px 0 6px; font-size: 14px; color: #7c2d12; }
.tool-app-selectsheet .ss-flagged { list-style: none; padding: 0; margin: 0; }
.tool-app-selectsheet .ss-flagged li { background: #fef2f2; border: 1px solid #fecaca; border-radius: 8px; padding: 8px 12px; margin-bottom: 6px; font-size: 13px; color: #7f1d1d; }
.tool-app-selectsheet .ss-flagged li.ss-soon { background: #fffbeb; border-color: #fde68a; color: #78350f; }
.tool-app-selectsheet .ss-flagged li.ss-none { background: #f0fdf4; border-color: #bbf7d0; color: #14532d; }
.tool-app-selectsheet .ss-actions { display: flex; gap: 10px; margin: 14px 0; flex-wrap: wrap; }
.tool-app-selectsheet .ss-saved { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-selectsheet .ss-saved li { display: flex; justify-content: space-between; align-items: center; background: #fff7ed; border-radius: 8px; padding: 8px 12px; margin-bottom: 6px; font-size: 14px; }
.tool-app-selectsheet .ss-saved button.ss-load { background: none; border: none; color: #C2410C; font-weight: 700; cursor: pointer; text-align: left; }
.tool-app-selectsheet .ss-saved button.ss-del { background: none; border: none; color: #b91c1c; cursor: pointer; font-size: 18px; }
.tool-app-selectsheet .tool-print-doc { display: none; }
@media print {
  .tool-app-selectsheet .ss-screen { display: none !important; }
  .tool-app-selectsheet .tool-print-doc { display: block !important; color: #000; }
  .tool-app-selectsheet .tool-print-doc h2 { border-bottom: 2px solid #333; padding-bottom: 6px; }
  .tool-app-selectsheet .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-selectsheet .tool-print-doc th, .tool-app-selectsheet .tool-print-doc td { border: 1px solid #999; padding: 6px; text-align: left; font-size: 12px; }
  .tool-app-selectsheet .tool-print-doc .ss-printtotals { margin: 12px 0; font-size: 14px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  var root = $('toolAppRoot');
  var LS_KEY = 'toolapp-selectsheet-projects';
  var STATUSES = ['Pending', 'Client picking', 'Approved'];
  var rooms = [];
  function newNumber() { return 'SS-2026-' + Math.floor(1000 + Math.random() * 9000); }
  function itemRow(it) {
    var tr = document.createElement('tr');
    tr.className = 'ss-itemrow';
    var opts = '';
    for (var i = 0; i < STATUSES.length; i++) {
      opts += '<option value="' + STATUSES[i] + '"' + (it.status === STATUSES[i] ? ' selected' : '') + '>' + STATUSES[i] + '</option>';
    }
    tr.innerHTML =
      '<td><input type="text" class="ss-item" placeholder="e.g. Backsplash tile" value="' + esc(it.item) + '"></td>' +
      '<td><input type="text" class="ss-vendor" placeholder="Vendor or link" value="' + esc(it.vendor) + '"></td>' +
      '<td><input type="number" class="ss-allow" min="0" step="0.01" value="' + (it.allow || 0) + '"></td>' +
      '<td><input type="number" class="ss-actual" min="0" step="0.01" value="' + (it.actual || 0) + '"></td>' +
      '<td><input type="date" class="ss-due" value="' + esc(it.due) + '"></td>' +
      '<td><select class="ss-status">' + opts + '</select></td>' +
      '<td><button type="button" class="ss-remove" aria-label="Remove item">\u00d7</button></td>';
    return tr;
  }
  function readState() {
    var out = [];
    var divs = root.querySelectorAll('#ss-rooms .ss-room');
    for (var r = 0; r < divs.length; r++) {
      var items = [];
      var rows = divs[r].querySelectorAll('tbody tr.ss-itemrow');
      for (var i = 0; i < rows.length; i++) {
        items.push({
          item: rows[i].querySelector('.ss-item').value,
          vendor: rows[i].querySelector('.ss-vendor').value,
          allow: parseFloat(rows[i].querySelector('.ss-allow').value) || 0,
          actual: parseFloat(rows[i].querySelector('.ss-actual').value) || 0,
          due: rows[i].querySelector('.ss-due').value,
          status: rows[i].querySelector('.ss-status').value
        });
      }
      out.push({ name: divs[r].getAttribute('data-room'), items: items });
    }
    return out;
  }
  function renderRooms() {
    var wrap = $('ss-rooms');
    wrap.innerHTML = '';
    rooms.forEach(function (room, ri) {
      var div = document.createElement('div');
      div.className = 'ss-room';
      div.setAttribute('data-room', room.name);
      var head = document.createElement('div');
      head.className = 'ss-roomhead';
      var h = document.createElement('h3');
      h.textContent = room.name;
      var btns = document.createElement('div');
      btns.className = 'ss-roomheadbtns';
      var addBtn = document.createElement('button');
      addBtn.type = 'button'; addBtn.className = 'ss-btn ss-btn-sm ss-additem';
      addBtn.textContent = '+ Add item'; addBtn.setAttribute('data-ri', ri);
      var delBtn = document.createElement('button');
      delBtn.type = 'button'; delBtn.className = 'ss-delroom';
      delBtn.setAttribute('aria-label', 'Delete room'); delBtn.setAttribute('data-ri', ri);
      delBtn.textContent = '\u00d7';
      btns.appendChild(addBtn);
      btns.appendChild(delBtn);
      head.appendChild(h);
      head.appendChild(btns);
      div.appendChild(head);
      var table = document.createElement('table');
      table.className = 'ss-table';
      var thead = document.createElement('thead');
      thead.innerHTML = '<tr><th>Selection</th><th>Vendor / link</th><th>Allowance</th><th>Actual</th><th>Due</th><th>Status</th><th></th></tr>';
      table.appendChild(thead);
      var tbody = document.createElement('tbody');
      room.items.forEach(function (it) { tbody.appendChild(itemRow(it)); });
      table.appendChild(tbody);
      div.appendChild(table);
      var rtot = document.createElement('div');
      rtot.className = 'ss-roomtotal';
      rtot.innerHTML = '<span>Room allowance</span><strong class="ss-rallow">$0.00</strong>' +
        '<span>Room actual (approved)</span><strong class="ss-ractual">$0.00</strong>';
      div.appendChild(rtot);
      wrap.appendChild(div);
    });
    recalc();
  }
  function renderFlagged(flagged) {
    var ul = $('ss-flagged');
    ul.innerHTML = '';
    if (!flagged.length) {
      var li = document.createElement('li');
      li.className = 'ss-none';
      li.textContent = 'Nothing pending and due within 7 days. All picks are on track.';
      ul.appendChild(li);
      return;
    }
    flagged.forEach(function (f) {
      var item = document.createElement('li');
      if (f.when.charAt(0) !== 'o') item.className = 'ss-soon';
      item.textContent = (f.room ? f.room + ' \u2014 ' : '') + (f.item || 'Unnamed selection') + ': ' + f.when + ' (' + f.due + ')';
      ul.appendChild(item);
    });
  }
  function recalc() {
    var state = readState();
    var totalAllow = 0, apprAllow = 0, apprActual = 0;
    var flagged = [];
    var today = new Date();
    today.setHours(0, 0, 0, 0);
    var divs = root.querySelectorAll('#ss-rooms .ss-room');
    for (var r = 0; r < state.length; r++) {
      var room = state[r];
      var rAllow = 0, rActual = 0;
      for (var i = 0; i < room.items.length; i++) {
        var it = room.items[i];
        totalAllow += it.allow;
        rAllow += it.allow;
        if (it.status === 'Approved') {
          apprAllow += it.allow;
          apprActual += it.actual;
          rActual += it.actual;
        } else if (it.due) {
          var d = new Date(it.due + 'T00:00:00');
          if (!isNaN(d.getTime())) {
            var days = Math.round((d.getTime() - today.getTime()) / 864e5);
            if (days < 0) flagged.push({ room: room.name, item: it.item, when: 'overdue by ' + (-days) + ' day' + (-days === 1 ? '' : 's'), due: it.due });
            else if (days <= 7) flagged.push({ room: room.name, item: it.item, when: 'due in ' + days + ' day' + (days === 1 ? '' : 's'), due: it.due });
          }
        }
      }
      if (divs[r]) {
        var ra = divs[r].querySelector('.ss-rallow');
        if (ra) ra.textContent = money(rAllow);
        var rac = divs[r].querySelector('.ss-ractual');
        if (rac) rac.textContent = money(rActual);
      }
    }
    rooms = state;
    $('ss-totalallow').textContent = money(totalAllow);
    $('ss-totalactual').textContent = money(apprActual);
    var diff = apprActual - apprAllow;
    var ou = $('ss-overunder');
    ou.textContent = (diff > 0 ? '+' : '') + money(diff);
    if (diff > 0) ou.classList.add('ss-neg'); else ou.classList.remove('ss-neg');
    renderFlagged(flagged);
    renderPrintDoc(state, totalAllow, apprAllow, apprActual);
  }
  function renderPrintDoc(state, totalAllow, apprAllow, apprActual) {
    var html = '<h1>' + esc($('ss-project').value || 'Selection sheet') + '</h1>' +
      '<p><strong>Client:</strong> ' + esc($('ss-client').value) + '<br>' +
      '<strong>Sheet #:</strong> ' + esc($('ss-number').value) + '</p>';
    for (var r = 0; r < state.length; r++) {
      var room = state[r];
      html += '<h2>' + esc(room.name) + '</h2>' +
        '<table><thead><tr><th>Selection</th><th>Vendor</th><th>Allowance</th><th>Actual</th><th>Due</th><th>Status</th></tr></thead><tbody>';
      for (var i = 0; i < room.items.length; i++) {
        var it = room.items[i];
        html += '<tr><td>' + esc(it.item) + '</td><td>' + esc(it.vendor) + '</td><td>' + money(it.allow) + '</td>' +
          '<td>' + money(it.actual) + '</td><td>' + esc(it.due) + '</td><td>' + esc(it.status) + '</td></tr>';
      }
      html += '</tbody></table>';
    }
    var diff = apprActual - apprAllow;
    html += '<div class="ss-printtotals"><p><strong>Total allowance:</strong> ' + money(totalAllow) + '<br>' +
      '<strong>Approved actual:</strong> ' + money(apprActual) + '<br>' +
      '<strong>Over / under:</strong> ' + money(diff) + '</p></div>';
    $('ss-printdoc').innerHTML = html;
  }
  function getProjects() {
    try { return JSON.parse(localStorage.getItem(LS_KEY)) || []; } catch (e) { return []; }
  }
  function setProjects(p) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(p)); } catch (e) {}
  }
  function saveProject() {
    var state = readState();
    var p = getProjects();
    var totalAllow = 0;
    state.forEach(function (room) {
      room.items.forEach(function (it) { totalAllow += it.allow; });
    });
    p.unshift({
      number: $('ss-number').value,
      project: $('ss-project').value,
      client: $('ss-client').value,
      rooms: state,
      totalAllow: totalAllow,
      savedAt: new Date().toISOString()
    });
    setProjects(p.slice(0, 50));
    renderSaved();
  }
  function renderSaved() {
    var p = getProjects();
    var ul = $('ss-saved');
    ul.innerHTML = '';
    if (!p.length) {
      var li = document.createElement('li');
      li.textContent = 'No saved projects yet.';
      ul.appendChild(li);
      return;
    }
    p.forEach(function (proj, idx) {
      var li = document.createElement('li');
      var load = document.createElement('button');
      load.type = 'button';
      load.className = 'ss-load';
      load.setAttribute('data-idx', idx);
      load.textContent = proj.number + ' \u2014 ' + (proj.project || 'Untitled project') + ' \u2014 ' + money(proj.totalAllow);
      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'ss-del';
      del.setAttribute('data-idx', idx);
      del.setAttribute('aria-label', 'Delete project');
      del.textContent = '\u00d7';
      li.appendChild(load);
      li.appendChild(del);
      ul.appendChild(li);
    });
  }
  function loadProject(idx) {
    var proj = getProjects()[idx];
    if (!proj) return;
    $('ss-number').value = proj.number;
    $('ss-project').value = proj.project || '';
    $('ss-client').value = proj.client || '';
    rooms = (proj.rooms || []).map(function (room) {
      return {
        name: room.name,
        items: (room.items || []).map(function (it) {
          return {
            item: it.item || '', vendor: it.vendor || '', allow: it.allow || 0,
            actual: it.actual || 0, due: it.due || '',
            status: STATUSES.indexOf(it.status) >= 0 ? it.status : 'Pending'
          };
        })
      };
    });
    renderRooms();
  }
  root.addEventListener('input', function () { recalc(); });
  root.addEventListener('change', function () { recalc(); });
  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'ss-addroom') {
      var name = $('ss-roomname').value.trim();
      if (name) {
        rooms = readState();
        rooms.push({ name: name, items: [{ item: '', vendor: '', allow: 0, actual: 0, due: '', status: 'Pending' }] });
        $('ss-roomname').value = '';
        renderRooms();
      }
      return;
    }
    if (t.id === 'ss-print') { recalc(); window.print(); return; }
    if (t.id === 'ss-save') { saveProject(); return; }
    var cls = (t.classList && t.classList.contains) ? t.classList : null;
    function has(c) { return !!cls && cls.contains(c); }
    if (has('ss-additem')) {
      var ri = parseInt(t.getAttribute('data-ri'), 10);
      rooms = readState();
      rooms[ri].items.push({ item: '', vendor: '', allow: 0, actual: 0, due: '', status: 'Pending' });
      renderRooms();
      return;
    }
    if (has('ss-delroom')) {
      rooms = readState();
      rooms.splice(parseInt(t.getAttribute('data-ri'), 10), 1);
      renderRooms();
      return;
    }
    if (has('ss-remove')) { t.closest('tr').remove(); recalc(); return; }
    if (has('ss-load')) { loadProject(parseInt(t.getAttribute('data-idx'), 10)); return; }
    if (has('ss-del')) {
      var p = getProjects();
      p.splice(parseInt(t.getAttribute('data-idx'), 10), 1);
      setProjects(p);
      renderSaved();
    }
  });
  (function init() {
    $('ss-number').value = newNumber();
    rooms = [{
      name: 'Kitchen',
      items: [{ item: 'Backsplash tile', vendor: '', allow: 800, actual: 0, due: '', status: 'Pending' }]
    }];
    renderRooms();
    renderSaved();
  })();
})();
